<?php $pageTitle='Search Books';require __DIR__.'/config/database.php';require __DIR__.'/includes/header.php';$q=trim($_GET['q']??'');$rows=[];if($q!==''){$s=$pdo->prepare("SELECT b.*,c.name category,a.name author FROM books b LEFT JOIN categories c ON c.id=b.category_id LEFT JOIN authors a ON a.id=b.author_id WHERE b.title LIKE ? OR b.isbn LIKE ? OR b.accession_no LIKE ? OR a.name LIKE ? ORDER BY b.title");$like="%$q%";$s->execute([$like,$like,$like,$like]);$rows=$s->fetchAll();}?><h2>Search Books</h2><form class="input-group mb-4"><input class="form-control" name="q" value="<?=h($q)?>" placeholder="Title, ISBN, accession or author"><button class="btn btn-primary">Search</button></form><div class="card card-body"><table class="table"><tr><th>Accession</th><th>Title</th><th>Author</th><th>Category</th><th>Available</th></tr><?php foreach($rows as $b):?><tr><td><?=h($b['accession_no'])?></td><td><?=h($b['title'])?></td><td><?=h($b['author']??'')?></td><td><?=h($b['category']??'')?></td><td><?=$b['available_copies']?></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/includes/footer.php';